import * as parser from "@babel/parser";
import traverse from "@babel/traverse";
import generate from "@babel/generator";
import * as t from "@babel/types";
import path from "path";
import { readFileSafe, writeFile } from "../utils/fs";
import { logger } from "../utils/logger";
import type { ExtractedString } from "./scanner";
import type { LocaleFile } from "./scaffolder";

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The result of transforming a single file.
 */
export interface TransformResult {
  /** Absolute path to the file */
  filePath: string;
  /** Whether the file was actually modified */
  modified: boolean;
  /** How many string replacements were made */
  replacements: number;
  /** The transformed source code (only set when modified is true) */
  newCode?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// AST builder helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Builds a t() call expression AST node for a plain string.
 *
 * Output: t('some.key')
 *
 * AST structure:
 *   CallExpression {
 *     callee: Identifier { name: 't' }
 *     arguments: [ StringLiteral { value: 'some.key' } ]
 *   }
 *
 * @param key - The full translation key e.g. "auth.signin.welcome_back"
 */
function buildTCall(key: string): t.CallExpression {
  return t.callExpression(t.identifier("t"), [t.stringLiteral(key)]);
}

/**
 * Builds a t() call expression with interpolation params.
 *
 * Output: t('some.key', { firstName, count })
 *
 * The params are passed as shorthand object properties:
 *   { firstName } is shorthand for { firstName: firstName }
 *
 * AST structure:
 *   CallExpression {
 *     callee: Identifier { name: 't' }
 *     arguments: [
 *       StringLiteral { value: 'some.key' },
 *       ObjectExpression {
 *         properties: [
 *           ObjectProperty { key: firstName, value: firstName, shorthand: true }
 *           ObjectProperty { key: count, value: count, shorthand: true }
 *         ]
 *       }
 *     ]
 *   }
 *
 * Why shorthand?
 * t('key', { firstName }) is more idiomatic than t('key', { firstName: firstName })
 * and produces cleaner output in the transformed files.
 *
 * @param key    - The full translation key
 * @param params - Variable names for interpolation
 */
function buildTCallWithParams(key: string, params: string[]): t.CallExpression {
  const paramsObject = t.objectExpression(
    params.map((param) => {
      const identifier = t.identifier(param);
      /**
       * Shorthand property: { firstName }
       * Both key and value are the same identifier,
       * and shorthand: true tells the code generator to use the short form.
       */
      const prop = t.objectProperty(identifier, identifier);
      prop.shorthand = true;
      return prop;
    }),
  );

  return t.callExpression(t.identifier("t"), [
    t.stringLiteral(key),
    paramsObject,
  ]);
}

/**
 * Wraps a call expression in a JSX expression container.
 *
 * Output: {t('some.key')}
 *
 * This is needed when replacing JSX text or JSX string expressions
 * with a t() call, because raw function calls are not valid JSX children —
 * they must be wrapped in curly braces.
 *
 * @param call - The t() CallExpression to wrap
 */
function buildJSXExpression(call: t.CallExpression): t.JSXExpressionContainer {
  return t.jsxExpressionContainer(call);
}

/**
 * Builds the useTranslation import declaration.
 *
 * Output: import { useTranslation } from 'react-i18next'
 *
 * AST structure:
 *   ImportDeclaration {
 *     specifiers: [ ImportSpecifier { imported: useTranslation } ]
 *     source: StringLiteral { value: 'react-i18next' }
 *   }
 */
function buildUseTranslationImport(): t.ImportDeclaration {
  return t.importDeclaration(
    [
      t.importSpecifier(
        t.identifier("useTranslation"),
        t.identifier("useTranslation"),
      ),
    ],
    t.stringLiteral("react-i18next"),
  );
}

/**
 * Builds the const { t } = useTranslation() declaration.
 *
 * Output: const { t } = useTranslation()
 *
 * AST structure:
 *   VariableDeclaration {
 *     kind: 'const'
 *     declarations: [
 *       VariableDeclarator {
 *         id: ObjectPattern { properties: [ t ] }
 *         init: CallExpression { callee: useTranslation }
 *       }
 *     ]
 *   }
 */
function buildUseTranslationCall(): t.VariableDeclaration {
  return t.variableDeclaration("const", [
    t.variableDeclarator(
      /**
       * Destructured pattern: { t }
       * ObjectPattern with a single RestElement-free property
       */
      t.objectPattern([
        t.objectProperty(
          t.identifier("t"),
          t.identifier("t"),
          false, // not computed
          true, // shorthand: { t } not { t: t }
        ),
      ]),
      /**
       * The initializer: useTranslation()
       * A call expression with no arguments
       */
      t.callExpression(t.identifier("useTranslation"), []),
    ),
  ]);
}

// ─────────────────────────────────────────────────────────────────────────────
// Lookup helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Looks up a plain string value in the extracted strings array.
 *
 * We match by filePath + originalText to find the correct ExtractedString.
 * This gives us the fullKey and params needed to build the t() call.
 *
 * Why not just build the key on the fly during transformation?
 * The scanner already did the work of building correct keys including
 * namespace computation and length trimming. Re-doing that logic here
 * would risk inconsistency. Better to look up the pre-computed result.
 *
 * @param value      - The raw string value found in the AST
 * @param filePath   - The file being transformed
 * @param strings    - All extracted strings from the scan
 * @param sourceType - Narrows the search to avoid false matches
 */
function findExtracted(
  value: string,
  filePath: string,
  strings: ExtractedString[],
  sourceType?: ExtractedString["sourceType"],
): ExtractedString | undefined {
  return strings.find(
    (s) =>
      s.filePath === filePath &&
      s.originalText === value.trim() &&
      (sourceType ? s.sourceType === sourceType : true),
  );
}

/**
 * Looks up a template literal in the extracted strings array.
 *
 * Template literals are stored with their {{param}} placeholders
 * as the originalText. We reconstruct the same format here to match.
 *
 * @param node     - The TemplateLiteral AST node
 * @param filePath - The file being transformed
 * @param strings  - All extracted strings from the scan
 */
function findExtractedTemplate(
  node: t.TemplateLiteral,
  filePath: string,
  strings: ExtractedString[],
): ExtractedString | undefined {
  /**
   * Reconstruct the display text from the template literal node.
   * This must match exactly how processTemplateLiteral() in scanner.ts
   * builds the text, including the {{paramName}} format.
   */
  let text = "";
  let argIndex = 0;

  node.quasis.forEach((quasi, i) => {
    text += quasi.value.cooked ?? quasi.value.raw;

    if (i < node.expressions.length) {
      const expr = node.expressions[i];
      let paramName: string;

      if (t.isIdentifier(expr)) {
        paramName = expr.name;
      } else if (t.isMemberExpression(expr) && t.isIdentifier(expr.property)) {
        paramName = expr.property.name;
      } else {
        paramName = `arg${argIndex++}`;
      }

      text += `{{${paramName}}}`;
    }
  });

  return strings.find(
    (s) => s.filePath === filePath && s.originalText === text.trim(),
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Component detection
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Returns true if the given node path is inside a React function component.
 *
 * We use this to decide where to inject `const { t } = useTranslation()`.
 * It must go inside a component body, not at module level.
 *
 * A function is considered a React component if:
 *   1. It is a function declaration or arrow function
 *   2. Its name starts with an uppercase letter (React convention)
 *      OR it is the default export
 *   3. It returns JSX (we check for JSXElement in its body)
 *
 * This is a heuristic — it covers the vast majority of real-world RN code.
 * Edge cases (HOCs, render props, etc.) are left for v2.
 *
 * @param nodePath - Any node path inside the file
 */
function isInsideComponent(nodePath: any): boolean {
  let current = nodePath.parentPath;

  while (current) {
    const node = current.node;

    // Arrow function assigned to a variable: const MyComp = () => ...
    if (t.isArrowFunctionExpression(node) || t.isFunctionExpression(node)) {
      const parent = current.parentPath?.node;

      // Check if it's assigned to an uppercase variable
      if (
        t.isVariableDeclarator(parent) &&
        t.isIdentifier(parent.id) &&
        /^[A-Z]/.test(parent.id.name)
      ) {
        return true;
      }

      // Check if it's the default export: export default () => ...
      if (t.isExportDefaultDeclaration(current.parentPath?.node)) {
        return true;
      }
    }

    // Function declaration: function MyComponent() { ... }
    if (t.isFunctionDeclaration(node)) {
      if (node.id && /^[A-Z]/.test(node.id.name)) {
        return true;
      }
      // export default function() { ... }
      if (t.isExportDefaultDeclaration(current.parentPath?.node)) {
        return true;
      }
    }

    current = current.parentPath;
  }

  return false;
}

// ─────────────────────────────────────────────────────────────────────────────
// Core replacement logic
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Attempts to replace a single expression node with a t() call.
 *
 * Handles four expression shapes:
 *   1. StringLiteral          → t('key')
 *   2. TemplateLiteral        → t('key', { params })
 *   3. ConditionalExpression  → recurse into branches
 *   4. LogicalExpression      → recurse into operands
 *
 * Returns the number of replacements made (for counting in results).
 *
 * @param nodePath   - The expression node path to replace
 * @param filePath   - Source file path for lookup
 * @param strings    - All extracted strings
 * @param sourceType - Expected source type for lookup narrowing
 */
function replaceExpression(
  nodePath: any,
  filePath: string,
  strings: ExtractedString[],
  sourceType: ExtractedString["sourceType"],
): number {
  const node = nodePath.node;
  let count = 0;

  if (t.isStringLiteral(node)) {
    const extracted = findExtracted(node.value, filePath, strings, sourceType);
    if (!extracted) return 0;

    const call =
      extracted.params.length > 0
        ? buildTCallWithParams(extracted.fullKey, extracted.params)
        : buildTCall(extracted.fullKey);

    nodePath.replaceWith(call);
    count++;
  } else if (t.isTemplateLiteral(node)) {
    const extracted = findExtractedTemplate(node, filePath, strings);
    if (!extracted) return 0;

    const call =
      extracted.params.length > 0
        ? buildTCallWithParams(extracted.fullKey, extracted.params)
        : buildTCall(extracted.fullKey);

    nodePath.replaceWith(call);
    count++;
  } else if (t.isConditionalExpression(node)) {
    /**
     * Ternary: replace each branch individually.
     * We don't replace the ternary itself — only its string leaves.
     *
     * isLoading ? "Loading" : "Done"
     * → isLoading ? t('ns.loading') : t('ns.done')
     */
    count += replaceExpression(
      nodePath.get("consequent"),
      filePath,
      strings,
      sourceType,
    );
    count += replaceExpression(
      nodePath.get("alternate"),
      filePath,
      strings,
      sourceType,
    );
  } else if (t.isLogicalExpression(node)) {
    /**
     * Logical: replace string operands.
     * flag && "Text" → flag && t('ns.text')
     */
    count += replaceExpression(
      nodePath.get("left"),
      filePath,
      strings,
      sourceType,
    );
    count += replaceExpression(
      nodePath.get("right"),
      filePath,
      strings,
      sourceType,
    );
  }

  return count;
}

// ─────────────────────────────────────────────────────────────────────────────
// Import and hook injection
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Checks whether useTranslation is already imported in the file.
 *
 * Looks for any import from 'react-i18next' that includes useTranslation.
 *
 * @param ast - The parsed AST of the file
 */
function hasUseTranslationImport(
  ast: ReturnType<typeof parser.parse>,
): boolean {
  let found = false;

  traverse(ast, {
    ImportDeclaration(nodePath) {
      if (nodePath.node.source.value !== "react-i18next") return;

      const hasIt = nodePath.node.specifiers.some(
        (spec) =>
          t.isImportSpecifier(spec) &&
          t.isIdentifier(spec.imported) &&
          spec.imported.name === "useTranslation",
      );

      if (hasIt) {
        found = true;
        nodePath.stop(); // stop traversal early
      }
    },
  });

  return found;
}

/**
 * Adds `import { useTranslation } from 'react-i18next'` to the file.
 *
 * Insertion strategy:
 *   - If there are existing imports, insert after the last import
 *   - If there are no imports, insert at the very top of the file
 *
 * Why after the last import?
 * Convention in JS/TS is to group imports together. Inserting after
 * the last existing import keeps the import block intact and doesn't
 * break any lint rules about import ordering.
 *
 * @param ast - The parsed AST (mutated in place)
 */
function addUseTranslationImport(ast: ReturnType<typeof parser.parse>): void {
  const body = ast.program.body;

  // Find the index of the last import declaration
  let lastImportIndex = -1;
  for (let i = 0; i < body.length; i++) {
    if (t.isImportDeclaration(body[i])) {
      lastImportIndex = i;
    }
  }

  const importNode = buildUseTranslationImport();

  if (lastImportIndex >= 0) {
    // Insert after the last import
    body.splice(lastImportIndex + 1, 0, importNode);
  } else {
    // No imports found — insert at the very top
    body.unshift(importNode);
  }
}

/**
 * Checks whether `const { t } = useTranslation()` is already declared
 * inside a given function body.
 *
 * @param bodyPath - The path of the function body block statement
 */
function hasTDeclaration(bodyPath: any): boolean {
  let found = false;

  bodyPath.traverse({
    VariableDeclaration(vPath: any) {
      const decl = vPath.node.declarations[0];
      if (!decl) return;

      if (
        t.isObjectPattern(decl.id) &&
        decl.id.properties.some(
          (p: any) =>
            t.isObjectProperty(p) &&
            t.isIdentifier(p.key) &&
            p.key.name === "t",
        ) &&
        t.isCallExpression(decl.init) &&
        t.isIdentifier(decl.init.callee) &&
        decl.init.callee.name === "useTranslation"
      ) {
        found = true;
        vPath.stop();
      }
    },
  });

  return found;
}

/**
 * Injects `const { t } = useTranslation()` at the top of a
 * function component body.
 *
 * Insertion strategy:
 *   Insert as the FIRST statement in the function body.
 *
 * Why first?
 * Hooks must be called at the top level of a component (React rules of hooks).
 * Placing it first makes it visible and respects the convention of
 * declaring hooks before other logic.
 *
 * @param bodyPath - The path of the function body block statement
 */
function addTDeclaration(bodyPath: any): void {
  if (hasTDeclaration(bodyPath)) return;

  const declaration = buildUseTranslationCall();
  bodyPath.unshiftContainer("body", declaration);
}

// ─────────────────────────────────────────────────────────────────────────────
// File-level transformer
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Transforms a single source file by replacing all translatable strings
 * with t() calls and injecting the useTranslation hook.
 *
 * Steps:
 *   1. Read the file
 *   2. Parse into AST
 *   3. Find strings that have entries in the locale file
 *   4. Replace each one with the appropriate t() call
 *   5. Inject useTranslation import if needed
 *   6. Inject const { t } = useTranslation() inside component if needed
 *   7. Generate new source code from the modified AST
 *
 * The function never writes to disk — it returns the new code.
 * Writing is handled by the replace command so dry-run is possible.
 *
 * @param filePath   - Absolute path to the source file
 * @param appRoot    - Absolute path to the app root
 * @param strings    - All extracted strings (from the scan)
 * @param localeData - The locale JSON file contents (for verification)
 */
export function transformFile(
  filePath: string,
  appRoot: string,
  strings: ExtractedString[],
  localeData: LocaleFile,
): TransformResult {
  const code = readFileSafe(filePath);
  if (!code) {
    return { filePath, modified: false, replacements: 0 };
  }

  /**
   * Find all extracted strings that belong to this file AND have
   * a corresponding entry in the locale file.
   *
   * The locale file check is important: if a string was extracted
   * but its key is not in the locale file (e.g. the locale was
   * generated with different settings), we skip it to avoid
   * replacing with a key that won't resolve.
   */
  const fileStrings = strings.filter(
    (s) => s.filePath === filePath && localeData[s.fullKey] !== undefined,
  );

  if (fileStrings.length === 0) {
    logger.debug(
      `No matching strings for ${path.relative(appRoot, filePath)} — skipping`,
    );
    return { filePath, modified: false, replacements: 0 };
  }

  // Parse the file into an AST
  let ast: ReturnType<typeof parser.parse>;
  try {
    ast = parser.parse(code, {
      sourceType: "module",
      plugins: ["jsx", "typescript", "decorators-legacy"],
    });
  } catch (err) {
    logger.warn(
      `Could not parse ${path.relative(appRoot, filePath)} — skipping`,
    );
    logger.debug(String(err));
    return { filePath, modified: false, replacements: 0 };
  }

  let totalReplacements = 0;
  let needsHook = false;

  traverse(ast, {
    // ── JSX text: <Text>Hello</Text> ─────────────────────────────────────────
    JSXText(nodePath) {
      const value = nodePath.node.value.trim();
      if (!value) return;

      const extracted = findExtracted(value, filePath, fileStrings, "jsx-text");
      if (!extracted) return;

      /**
       * JSXText must be replaced with a JSXExpressionContainer.
       * We can't just swap the text node for a call expression directly —
       * JSX only accepts expression containers as children when the
       * content is dynamic.
       *
       * Before: <Text>Hello</Text>
       * After:  <Text>{t('ns.hello')}</Text>
       */
      const call = buildTCall(extracted.fullKey);
      nodePath.replaceWith(buildJSXExpression(call));
      totalReplacements++;
      needsHook = true;
    },

    // ── JSX expression container: <Text>{"Hello"}</Text> ────────────────────
    JSXExpressionContainer(nodePath) {
      /**
       * Only process containers that are JSX children, not prop values.
       * className={`flex`} is also a JSXExpressionContainer but its
       * parent is a JSXAttribute, not a JSXElement.
       */
      const parent = nodePath.parent;
      if (!t.isJSXElement(parent) && !t.isJSXFragment(parent)) return;

      const exprPath = nodePath.get("expression") as any;
      const count = replaceExpression(
        exprPath,
        filePath,
        fileStrings,
        "jsx-expression",
      );

      if (count > 0) {
        totalReplacements += count;
        needsHook = true;
      }
    },

    // ── JSX attribute: <Comp title="Hello" /> ────────────────────────────────
    JSXAttribute(nodePath) {
      const { name, value } = nodePath.node;

      const propName = t.isJSXIdentifier(name) ? name.name : null;
      if (!propName) return;

      if (!t.isStringLiteral(value)) return;

      const extracted = findExtracted(
        value.value,
        filePath,
        fileStrings,
        "jsx-attribute",
      );
      if (!extracted) return;

      /**
       * String prop must be converted to a JSX expression.
       *
       * Before: <Button title="Submit" />
       * After:  <Button title={t('ns.submit')} />
       *
       * The string literal value is replaced with a JSXExpressionContainer
       * wrapping the t() call.
       */
      const call = buildTCall(extracted.fullKey);
      nodePath.node.value = buildJSXExpression(call);
      totalReplacements++;
      needsHook = true;
    },

    // ── Alert.alert() calls ──────────────────────────────────────────────────
    CallExpression(nodePath) {
      const { callee, arguments: args } = nodePath.node;

      // Detect Alert.alert
      const isAlert =
        t.isMemberExpression(callee) &&
        t.isIdentifier(callee.object) &&
        callee.object.name === "Alert" &&
        t.isIdentifier(callee.property) &&
        callee.property.name === "alert";

      if (isAlert) {
        args.forEach((arg, index) => {
          if (!t.isStringLiteral(arg)) return;

          const extracted = findExtracted(
            arg.value,
            filePath,
            fileStrings,
            "alert",
          );
          if (!extracted)
            return /**
             * Replace the string argument in-place.
             * Alert.alert('Title', 'Message')
             * → Alert.alert(t('ns.title'), t('ns.message'))
             */;
          (nodePath.node.arguments as any[])[index] = buildTCall(
            extracted.fullKey,
          );
          totalReplacements++;
          needsHook = true;
        });
        return;
      }

      // Detect custom call patterns
      let calleeName: string | null = null;

      if (t.isIdentifier(callee)) {
        calleeName = callee.name;
      } else if (
        t.isMemberExpression(callee) &&
        t.isIdentifier(callee.object) &&
        t.isIdentifier(callee.property)
      ) {
        calleeName = `${callee.object.name}.${callee.property.name}`;
      }

      if (!calleeName) return;

      args.forEach((arg, index) => {
        if (!t.isStringLiteral(arg)) return;

        const extracted = findExtracted(
          arg.value,
          filePath,
          fileStrings,
          "call",
        );
        if (!extracted) return;
        (nodePath.node.arguments as any[])[index] = buildTCall(
          extracted.fullKey,
        );
        totalReplacements++;
        needsHook = true;
      });
    },

    // ── Throw statements: throw new Error('msg') ─────────────────────────────
    ThrowStatement(nodePath) {
      const { argument } = nodePath.node;

      if (
        t.isNewExpression(argument) &&
        t.isIdentifier(argument.callee) &&
        argument.callee.name === "Error"
      ) {
        argument.arguments.forEach((arg, index) => {
          if (!t.isStringLiteral(arg)) return;

          const extracted = findExtracted(
            arg.value,
            filePath,
            fileStrings,
            "throw",
          );
          if (!extracted) return;
          (argument.arguments as any[])[index] = buildTCall(extracted.fullKey);
          totalReplacements++;
          /**
           * Note: we do NOT set needsHook = true for throw statements.
           *
           * Why? throw statements are usually outside JSX render paths
           * and may appear in utility functions, event handlers, or
           * async functions that are not React components.
           *
           * If the file has other JSX replacements, needsHook will be
           * set by those. If throw is the ONLY thing replaced, injecting
           * useTranslation would be incorrect — hooks can't be called
           * outside components.
           *
           * The t() call will still work as long as useTranslation is
           * available in scope from another replacement in the same file.
           */
        });
      }
    },

    // ── Inject useTranslation hook into components ───────────────────────────
    /**
     * We visit function bodies and inject the hook at the top.
     *
     * We use a post-traversal approach: after all replacements are done,
     * we know which files need the hook (needsHook flag). But since
     * traverse only runs once, we inject during traversal whenever we
     * enter a component body.
     *
     * The hasTDeclaration check prevents duplicate injections when
     * a file has multiple components.
     */
    "FunctionDeclaration|FunctionExpression|ArrowFunctionExpression"(
      nodePath: any,
    ) {
      if (!needsHook) return;
      if (!totalReplacements) return;

      const body = nodePath.get("body");

      /**
       * Only inject into block-body functions: () => { ... }
       * Not into expression-body arrows: () => <JSX />
       *
       * Expression bodies can't have hook declarations.
       * If an arrow function returns JSX directly without a block body,
       * we skip it — the parent function will handle it.
       */
      if (!t.isBlockStatement(body.node)) return;

      /**
       * Check that this function looks like a React component.
       * We don't want to inject hooks into utility functions,
       * event handlers, or async functions.
       */
      const funcNode = nodePath.node;

      const funcName =
        t.isFunctionDeclaration(funcNode) && funcNode.id
          ? funcNode.id.name
          : t.isVariableDeclarator(nodePath.parent) &&
              t.isIdentifier(nodePath.parent.id)
            ? nodePath.parent.id.name
            : null;

      /**
       * A function is a component if:
       *   - Its name starts with an uppercase letter, OR
       *   - It is the default export (no name required)
       */
      const isComponent =
        (funcName && /^[A-Z]/.test(funcName)) ||
        t.isExportDefaultDeclaration(nodePath.parentPath?.node);

      if (!isComponent) return;

      addTDeclaration(body);
    },
  });

  if (totalReplacements === 0) {
    return { filePath, modified: false, replacements: 0 };
  }

  // ── Inject import ─────────────────────────────────────────────────────────
  /**
   * Add the useTranslation import after traversal is complete.
   * We do this after traverse (not during) because modifying the
   * program body during traversal can cause nodes to be visited twice.
   */
  if (needsHook && !hasUseTranslationImport(ast)) {
    addUseTranslationImport(ast);
  }

  // ── Generate new code ─────────────────────────────────────────────────────
  /**
   * @babel/generator converts the modified AST back to source code.
   *
   * Options:
   *   retainLines: false — don't force original line numbers
   *   concise: false     — produce readable formatting
   *   jsescOption        — don't escape unicode characters (preserves
   *                        accented chars, emoji, Arabic, etc.)
   */
  const output = generate(
    ast,
    {
      retainLines: false,
      concise: false,
      jsescOption: { minimal: true },
    },
    code,
  );

  return {
    filePath,
    modified: true,
    replacements: totalReplacements,
    newCode: output.code,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Project-level transformer
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Transforms all files in the project that have translatable strings.
 *
 * This function only computes transformations — it does not write to disk.
 * The replace command decides whether to write based on dry-run mode
 * and user confirmation.
 *
 * @param appRoot    - Absolute path to the app root
 * @param strings    - All extracted strings from the scan
 * @param localeData - The locale JSON file contents
 */
export async function transformProject(
  appRoot: string,
  strings: ExtractedString[],
  localeData: LocaleFile,
): Promise<TransformResult[]> {
  /**
   * Get unique file paths from the extracted strings.
   * We only process files that actually have strings to replace.
   */
  const uniqueFiles = [...new Set(strings.map((s) => s.filePath))];

  logger.dim(`  Processing ${uniqueFiles.length} file(s)...`);

  const results: TransformResult[] = [];

  for (const filePath of uniqueFiles) {
    const result = transformFile(filePath, appRoot, strings, localeData);
    results.push(result);

    if (result.modified) {
      logger.dim(
        `  ✓ ${path.relative(appRoot, filePath)} — ${result.replacements} replacement(s)`,
      );
    } else {
      logger.debug(`  ○ ${path.relative(appRoot, filePath)} — no changes`);
    }
  }

  return results;
}
